// src/features/search/providers/elasticsearch/elasticsearch-field-mapping.test.ts

/**
 * The Elasticsearch mapping for every field type is what it was before the language-analysed
 * types became a shared list. The fixture was generated by running origin/main's
 * mapFieldTypeToES (7d51f969) over every type the Azure mapper knows, the ES-only types in
 * its switch and an unknown type, each plain, with autocomplete, with a custom analyzer,
 * facetable, and all three together.
 */

import { describe, expect, it, vi } from 'vitest';


import { FIELD_TYPE_TO_EDM } from '../azure-ai-search/azure-constants';

import { mapFieldTypeToES } from './elasticsearch-field-mapping';
import fixture from './elasticsearch-field-mapping.origin-main.fixture.json';
import { INTERAKT_TEXT_ANALYZER, INTERAKT_TEXT_SEARCH_ANALYZER } from './elasticsearch.constants';

import { LANGUAGE_ANALYSED_FIELD_TYPES } from '@/shared/constants/search-index.constants';

const VARIANTS: Record<string, Record<string, unknown>> = {
    plain: {},
    autocomplete: { isAutocomplete: true },
    custom: { customAnalyzer: 'my_an' },
    facet: { isFacetable: true },
    both: { isAutocomplete: true, customAnalyzer: 'my_an', isFacetable: true },
};
const table = fixture as Record<string, Record<string, unknown>>;

describe('mapFieldTypeToES', () => {
    it('covers every Azure field type and the ES-only ones in the fixture', () => {
        for (const type of [...Object.keys(FIELD_TYPE_TO_EDM), 'slug', 'id', 'uuid', 'phone', 'geo_point', 'nested', 'object']) {
            expect(table, type).toHaveProperty(type);
        }
    });

    for (const [fieldType, expected] of Object.entries(table)) {
        it(`maps ${fieldType} as origin/main did, in every variant`, () => {
            vi.spyOn(console, 'warn').mockImplementation(() => undefined);
            for (const [variant, flags] of Object.entries(VARIANTS)) {
                const field = { fieldType, isAutocomplete: false, isFacetable: false, customAnalyzer: null, ...flags };
                expect(mapFieldTypeToES(field as never), `${fieldType} ${variant}`).toEqual(expected[variant]);
            }
        });
    }

    it('gives the language analyzer pair to the prose types and only those', () => {
        for (const fieldType of LANGUAGE_ANALYSED_FIELD_TYPES) {
            expect(mapFieldTypeToES({ fieldType, isAutocomplete: false, isFacetable: false, customAnalyzer: null } as never)).toEqual({
                type: 'text',
                analyzer: INTERAKT_TEXT_ANALYZER,
                search_analyzer: INTERAKT_TEXT_SEARCH_ANALYZER,
            });
        }
        for (const fieldType of ['keyword', 'url', 'email', 'array', 'json']) {
            expect(mapFieldTypeToES({ fieldType, isAutocomplete: false, isFacetable: false, customAnalyzer: null } as never)).not.toHaveProperty('analyzer');
        }
    });
});
